use derive_more :: Display ; use serde :: { Deserialize , Serialize } ; use uuid :: Uuid ; impl WorkspaceId { # [doc = " Generate a new random workspace ID"] pub fn generate () -> Self { Self (Uuid :: new_v4 ()) } # [doc = " Parse a workspace ID from a string"] # [doc = ""] # [doc = " # Errors"] # [doc = " Returns an error if the string is not a valid UUID"] pub fn from_string (s : & str) -> anyhow :: Result < Self > { Ok (Self (Uuid :: parse_str (s) ?)) } # [doc = " Get the inner UUID"] pub fn inner (& self) -> Uuid { self . 0 } }